cat > src/App.jsx <<'EOF'
import React, { useEffect, useMemo, useRef, useState } from 'react'
import { meetings, SPEAKER_HUES } from './data.js'

const fmtClock = (s) => {
  const m = Math.floor(s / 60)
  return `${m}:${String(Math.floor(s % 60)).padStart(2, '0')}`
}
const fmtDate = (iso) =>
  new Date(iso).toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' }) +
  ' at ' +
  new Date(iso).toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' })
const initials = (n) => n.split(' ').map((p) => p[0]).slice(0, 2).join('')

function useHashRoute() {
  const [hash, setHash] = useState(window.location.hash)
  useEffect(() => {
    const on = () => setHash(window.location.hash)
    window.addEventListener('hashchange', on)
    return () => window.removeEventListener('hashchange', on)
  }, [])
  const m = hash.match(/^#\/meeting\/(.+)$/)
  return m ? { name: 'meeting', id: m[1] } : { name: 'list' }
}

const hueFor = (meeting, speaker) =>
  SPEAKER_HUES[Math.max(0, meeting.speakers.indexOf(speaker)) % SPEAKER_HUES.length]

/* ---------- search ---------- */
const STOP = new Set('the a an and or of to in on for is are was were what who when did do does we you it that this with about from how'.split(' '))
const terms = (q) => q.toLowerCase().split(/\W+/).filter((w) => w && !STOP.has(w))

function scoreLines(meeting, q) {
  const ts = terms(q)
  if (!ts.length) return []
  return meeting.transcript
    .map((l) => {
      const low = l.x.toLowerCase()
      return { line: l, score: ts.reduce((n, t) => n + (low.includes(t) ? 1 : 0), 0) }
    })
    .filter((r) => r.score > 0)
    .sort((a, b) => b.score - a.score || a.line.t - b.line.t)
}

function Mark({ text, q }) {
  const ts = terms(q)
  if (!ts.length) return text
  const re = new RegExp(`(${ts.map((t) => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('|')})`, 'gi')
  return text.split(re).map((p, i) => (i % 2 ? <mark key={i}>{p}</mark> : p))
}

/* ---------- list ---------- */
function Rail({ route }) {
  return (
    <nav className="rail" aria-label="Main">
      <a className="brand" href="#/">
        <span className="brand-mark" aria-hidden="true" />
        Sounding
      </a>
      <a className={route.name === 'list' ? 'rail-link on' : 'rail-link'} href="#/">Meetings</a>
      <span className="rail-note">Sample data. No recordings leave this machine.</span>
    </nav>
  )
}

function MeetingRow({ m, q }) {
  const hits = q ? scoreLines(m, q) : []
  const open = m.actions.filter((a) => !a.done).length
  return (
    <a className="row" href={`#/meeting/${m.id}`}>
      <div className="row-main">
        <h3>{m.title}</h3>
        <p className="row-meta">
          {fmtDate(m.date)} · {Math.round(m.duration / 60)} min
        </p>
        {q && hits[0] && (
          <p className="row-hit">
            <span className="clock">{fmtClock(hits[0].line.t)}</span>
            <Mark text={hits[0].line.x} q={q} />
          </p>
        )}
      </div>
      <div className="row-side">
        <div className="faces" aria-label={m.speakers.join(', ')}>
          {m.speakers.slice(0, 4).map((s) => (
            <span key={s} className="face" style={{ background: hueFor(m, s) }} title={s}>{initials(s)}</span>
          ))}
        </div>
        <span className={open ? 'pill open' : 'pill'}>{open ? `${open} open` : 'All done'}</span>
      </div>
    </a>
  )
}

function List() {
  const [tab, setTab] = useState('mine')
  const [q, setQ] = useState('')
  const shown = useMemo(() => {
    const base = meetings.filter((m) => (q ? true : m.scope === tab))
    if (!q) return base
    return base.filter((m) => scoreLines(m, q).length || m.title.toLowerCase().includes(q.toLowerCase()))
  }, [tab, q])
  return (
    <main className="page">
      <header className="page-head">
        <h1>Meetings</h1>
        <label className="search">
          <span className="sr">Search all meetings</span>
          <input
            type="search"
            placeholder="Search every transcript, for example “renewals”"
            value={q}
            onChange={(e) => setQ(e.target.value)}
          />
        </label>
      </header>
      {!q && (
        <div className="tabs" role="tablist">
          {[['mine', 'My calls'], ['team', 'Team calls']].map(([k, label]) => (
            <button key={k} role="tab" aria-selected={tab === k} className={tab === k ? 'tab on' : 'tab'} onClick={() => setTab(k)}>
              {label}
            </button>
          ))}
        </div>
      )}
      {q && <p className="search-note">{shown.length} of {meetings.length} meetings match “{q}”</p>}
      <div className="rows">
        {shown.map((m) => <MeetingRow key={m.id} m={m} q={q} />)}
        {!shown.length && <p className="empty">No meeting mentions “{q}”. Try a different word.</p>}
      </div>
    </main>
  )
}

/* ---------- detail ---------- */
function TalkStrip({ meeting, playDur, now, onSeek }) {
  const segs = meeting.transcript.map((l, i) => {
    const end = meeting.transcript[i + 1]?.t ?? playDur
    return { l, left: (l.t / playDur) * 100, width: ((end - l.t) / playDur) * 100 }
  })
  const share = {}
  segs.forEach((s) => {
    share[s.l.s] = (share[s.l.s] || 0) + s.width
  })
  const total = Object.values(share).reduce((a, b) => a + b, 0)
  return (
    <div className="strip-wrap">
      <div
        className="strip"
        role="slider"
        tabIndex={0}
        aria-label="Recording position"
        aria-valuemin={0}
        aria-valuemax={Math.round(playDur)}
        aria-valuenow={Math.round(now)}
        onClick={(e) => {
          const r = e.currentTarget.getBoundingClientRect()
          onSeek(((e.clientX - r.left) / r.width) * playDur)
        }}
        onKeyDown={(e) => {
          if (e.key === 'ArrowRight') onSeek(Math.min(playDur, now + 5))
          if (e.key === 'ArrowLeft') onSeek(Math.max(0, now - 5))
        }}
      >
        {segs.map((s, i) => (
          <span key={i} className="seg" style={{ left: `${s.left}%`, width: `${s.width}%`, background: hueFor(meeting, s.l.s) }} />
        ))}
        <span className="playhead" style={{ left: `${(now / playDur) * 100}%` }} />
      </div>
      <ul className="legend">
        {meeting.speakers.filter((s) => share[s]).map((s) => (
          <li key={s}>
            <i style={{ background: hueFor(meeting, s) }} />
            {s} <b>{Math.round((share[s] / total) * 100)}%</b>
          </li>
        ))}
      </ul>
    </div>
  )
}

function Transcript({ meeting, now, onSeek, q }) {
  const active = meeting.transcript.reduce((a, l, i) => (l.t <= now ? i : a), -1)
  const refs = useRef([])
  const follow = useRef(true)
  useEffect(() => {
    if (follow.current && refs.current[active]) refs.current[active].scrollIntoView({ block: 'nearest', behavior: 'smooth' })
  }, [active])
  return (
    <ol className="transcript" onWheel={() => (follow.current = false)} onTouchMove={() => (follow.current = false)}>
      {meeting.transcript.map((l, i) => {
        const dim = q && !terms(q).some((t) => l.x.toLowerCase().includes(t))
        return (
          <li key={i} ref={(el) => (refs.current[i] = el)} className={`line${i === active ? ' active' : ''}${dim ? ' dim' : ''}`}>
            <button className="stamp" onClick={() => { follow.current = true; onSeek(l.t) }} aria-label={`Jump to ${fmtClock(l.t)}`}>
              {fmtClock(l.t)}
            </button>
            <div>
              <span className="who" style={{ color: hueFor(meeting, l.s) }}>{l.s}</span>
              <p><Mark text={l.x} q={q} /></p>
            </div>
          </li>
        )
      })}
    </ol>
  )
}

function Summary({ s }) {
  return (
    <div className="stack">
      <section>
        <h2>Overview</h2>
        <p className="lead">{s.overview}</p>
      </section>
      <section>
        <h2>Key points</h2>
        <ul className="bullets">{s.points.map((p) => <li key={p}>{p}</li>)}</ul>
      </section>
      <section>
        <h2>Decisions</h2>
        <ul className="bullets decisions">{s.decisions.map((p) => <li key={p}>{p}</li>)}</ul>
      </section>
    </div>
  )
}

function Actions({ meeting }) {
  const key = `sounding:actions:${meeting.id}`
  const [done, setDone] = useState(() => {
    try {
      return JSON.parse(localStorage.getItem(key)) ?? Object.fromEntries(meeting.actions.map((a) => [a.id, a.done]))
    } catch {
      return Object.fromEntries(meeting.actions.map((a) => [a.id, a.done]))
    }
  })
  const toggle = (id) => {
    const next = { ...done, [id]: !done[id] }
    setDone(next)
    try { localStorage.setItem(key, JSON.stringify(next)) } catch { /* storage unavailable */ }
  }
  return (
    <ul className="actions">
      {meeting.actions.map((a) => (
        <li key={a.id} className={done[a.id] ? 'done' : ''}>
          <label>
            <input type="checkbox" checked={!!done[a.id]} onChange={() => toggle(a.id)} />
            <span className="box" aria-hidden="true" />
            <span className="atext">{a.text}</span>
          </label>
          <span className="ameta">
            <span className="face sm" style={{ background: hueFor(meeting, a.owner) }}>{initials(a.owner)}</span>
            {a.owner} · due {a.due}
          </span>
        </li>
      ))}
    </ul>
  )
}

function Ask({ meeting, onSeek }) {
  const [q, setQ] = useState('')
  const [thread, setThread] = useState([])
  const ask = (text) => {
    const question = text.trim()
    if (!question) return
    const lower = question.toLowerCase()
    let answer
    if (/action|todo|follow.?up|owe|task/.test(lower)) {
      answer = { text: 'Open action items:', items: meeting.actions.filter((a) => !a.done).map((a) => `${a.owner}: ${a.text} (due ${a.due})`) }
    } else if (/decid|decision|agree/.test(lower)) {
      answer = { text: 'Decisions from this meeting:', items: meeting.summary.decisions }
    } else if (/summar|overview|about/.test(lower)) {
      answer = { text: meeting.summary.overview, items: [] }
    } else {
      const hits = scoreLines(meeting, question).slice(0, 2)
      answer = hits.length
        ? { text: 'Closest moments in the transcript:', cites: hits.map((h) => h.line) }
        : { text: 'Nothing in this meeting matches that. Try a specific word from the conversation.', items: [] }
    }
    setThread((t) => [...t, { question, answer }])
    setQ('')
  }
  return (
    <div className="ask">
      <div className="thread" aria-live="polite">
        {!thread.length && (
          <div className="suggest">
            <p>Ask about this meeting.</p>
            {['What did we decide?', 'What are the action items?', 'Who mentioned renewals?'].map((s) => (
              <button key={s} onClick={() => ask(s)}>{s}</button>
            ))}
          </div>
        )}
        {thread.map((m, i) => (
          <div key={i} className="qa">
            <p className="q">{m.question}</p>
            <div className="a">
              <p>{m.answer.text}</p>
              {m.answer.items?.length > 0 && <ul className="bullets">{m.answer.items.map((x) => <li key={x}>{x}</li>)}</ul>}
              {m.answer.cites?.map((c, j) => (
                <button key={j} className="cite" onClick={() => onSeek(c.t)}>
                  <span className="clock">{fmtClock(c.t)}</span>
                  <span><b>{c.s}:</b> {c.x}</span>
                </button>
              ))}
            </div>
          </div>
        ))}
      </div>
      <form onSubmit={(e) => { e.preventDefault(); ask(q) }} className="ask-form">
        <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Ask about this meeting" aria-label="Ask about this meeting" />
        <button type="submit">Ask</button>
      </form>
    </div>
  )
}

function Meeting({ id }) {
  const meeting = meetings.find((m) => m.id === id)
  // The sample transcripts are short excerpts, so the mock player spans the excerpt, not the full call length.
  const playDur = meeting ? meeting.transcript[meeting.transcript.length - 1].t + 25 : 1
  const [now, setNow] = useState(0)
  const [playing, setPlaying] = useState(false)
  const [tab, setTab] = useState('summary')
  const [find, setFind] = useState('')

  useEffect(() => {
    setNow(0); setPlaying(false); setTab('summary'); setFind('')
  }, [id])
  useEffect(() => {
    if (!playing) return
    const t = setInterval(() => setNow((n) => (n + 1 >= playDur ? (setPlaying(false), playDur) : n + 1)), 1000)
    return () => clearInterval(t)
  }, [playing, playDur])

  if (!meeting) {
    return (
      <main className="page">
        <p className="empty">That meeting doesn’t exist. <a href="#/">Back to meetings</a></p>
      </main>
    )
  }
  const seek = (t) => { setNow(t); setPlaying(true) }
  const open = meeting.actions.filter((a) => !a.done).length

  return (
    <main className="detail">
      <header className="d-head">
        <a className="back" href="#/">Meetings</a>
        <h1>{meeting.title}</h1>
        <p className="row-meta">
          {fmtDate(meeting.date)} · {Math.round(meeting.duration / 60)} min · {meeting.speakers.join(', ')}
        </p>
      </header>

      <div className="d-grid">
        <section className="left" aria-label="Recording and transcript">
          <div className="player">
            <button className="play" onClick={() => setPlaying((p) => !p)} aria-label={playing ? 'Pause' : 'Play'}>
              {playing ? <svg viewBox="0 0 24 24" width="18" height="18"><path d="M7 5h4v14H7zM13 5h4v14h-4z" fill="currentColor" /></svg> : <svg viewBox="0 0 24 24" width="18" height="18"><path d="M8 5v14l11-7z" fill="currentColor" /></svg>}
            </button>
            <span className="time">{fmtClock(now)} <span>/ {fmtClock(playDur)}</span></span>
            <span className="demo">Mock player: no audio</span>
          </div>
          <TalkStrip meeting={meeting} playDur={playDur} now={now} onSeek={seek} />
          <label className="find">
            <span className="sr">Find in transcript</span>
            <input type="search" placeholder="Find in transcript" value={find} onChange={(e) => setFind(e.target.value)} />
          </label>
          <Transcript meeting={meeting} now={now} onSeek={seek} q={find} />
        </section>

        <aside className="right" aria-label="AI notes">
          <div className="tabs" role="tablist">
            {[['summary', 'Summary'], ['actions', `Action items${open ? ` (${open})` : ''}`], ['ask', 'Ask']].map(([k, label]) => (
              <button key={k} role="tab" aria-selected={tab === k} className={tab === k ? 'tab on' : 'tab'} onClick={() => setTab(k)}>{label}</button>
            ))}
          </div>
          <div className="panel">
            {tab === 'summary' && <Summary s={meeting.summary} />}
            {tab === 'actions' && <Actions meeting={meeting} />}
            {tab === 'ask' && <Ask meeting={meeting} onSeek={seek} />}
          </div>
        </aside>
      </div>
    </main>
  )
}

export default function App() {
  const route = useHashRoute()
  return (
    <div className="shell">
      <Rail route={route} />
      {route.name === 'meeting' ? <Meeting id={route.id} /> : <List />}
    </div>
  )
}
