// Client for the pipeline API (server.py on the GPU box, proxied at /api).
import { useCallback, useEffect, useRef, useState } from 'react'

async function req(path, opts = {}) {
  const r = await fetch(`/api${path}`, opts)
  const body = await r.json().catch(() => ({}))
  if (!r.ok) throw new Error(body.detail || `Request failed (${r.status})`)
  return body
}

export const api = {
  health: () => req('/health'),
  list: () => req('/meetings'),
  get: (id) => req(`/meetings/${id}`),
  patch: (id, body) =>
    req(`/meetings/${id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) }),
  remove: (id) => req(`/meetings/${id}`, { method: 'DELETE' }),
  ask: (id, question) =>
    req(`/meetings/${id}/ask`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ question }) }),
  audioUrl: (id) => `/api/meetings/${id}/audio`,
  // XHR rather than fetch so the upload can report progress.
  upload: (file, title, onProgress) =>
    new Promise((resolve, reject) => {
      const x = new XMLHttpRequest()
      const form = new FormData()
      form.append('file', file)
      form.append('title', title || '')
      x.open('POST', '/api/meetings')
      x.upload.onprogress = (e) => e.lengthComputable && onProgress(e.loaded / e.total)
      x.onload = () => {
        let body = {}
        try { body = JSON.parse(x.responseText) } catch { /* not JSON */ }
        x.status < 300 ? resolve(body) : reject(new Error(body.detail || `Upload failed (${x.status})`))
      }
      x.onerror = () => reject(new Error('Upload failed. Check that the pipeline server is reachable.'))
      x.send(form)
    }),
}

export const STAGES = {
  queued: 'Waiting to start',
  converting: 'Preparing audio',
  speakers: 'Finding speakers',
  transcribing: 'Transcribing',
  summarizing: 'Writing notes',
  done: 'Ready',
  failed: 'Failed',
}
export const busy = (stage) => stage && stage !== 'done' && stage !== 'failed'

// The meeting list, polled faster while anything is still processing.
export function useRemoteList() {
  const [rows, setRows] = useState([])
  const [online, setOnline] = useState(null)
  const timer = useRef()
  const refresh = useCallback(async () => {
    clearTimeout(timer.current)
    let next = 15000
    try {
      const r = await api.list()
      setRows(r)
      setOnline(true)
      if (r.some((m) => busy(m.stage))) next = 2500
    } catch {
      setOnline(false)
    }
    timer.current = setTimeout(refresh, next)
  }, [])
  useEffect(() => {
    refresh()
    return () => clearTimeout(timer.current)
  }, [refresh])
  return { rows, online, refresh }
}

// Speaker labels ("Speaker 2") mapped to names people have given them.
export const displayName = (m, label) => (m.names && m.names[label]) || label

// Shape a server meeting like the sample meetings so the same views render both.
export function adapt(m) {
  const dn = (s) => displayName(m, s)
  return {
    id: m.id,
    remote: true,
    stage: m.stage,
    error: m.error,
    title: m.title,
    date: m.date,
    duration: m.duration || 0,
    scope: m.scope || 'mine',
    labels: m.speakers,
    names: m.names || {},
    speakers: (m.speakers || []).map(dn),
    summary: m.summary || { overview: '', points: [], decisions: [] },
    actions: (m.actions || []).map((a) => ({ ...a, owner: a.owner ? dn(a.owner) : null })),
    transcript: (m.transcript || []).map((l) => ({ t: l.t, s: dn(l.s), x: l.x })),
    timings: m.timings,
  }
}

import React, { useEffect, useMemo, useRef, useState } from 'react'
import { meetings as samples, SPEAKER_HUES } from './data.js'
import { api, adapt, busy, STAGES, useRemoteList } from './api.js'

const fmtClock = (s) => {
  const m = Math.floor(s / 60)
  return `${m}:${String(Math.floor(s % 60)).padStart(2, '0')}`
}
const fmtDate = (iso) =>
  new Date(iso).toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' }) +
  ' at ' +
  new Date(iso).toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' })
const fmtMinutes = (s) => (s ? `${Math.max(1, Math.round(s / 60))} min` : '')
const initials = (n) =>
  /^Speaker \d+$/.test(n) ? `S${n.split(' ')[1]}` : n.split(' ').map((p) => p[0]).slice(0, 2).join('')

function useHashRoute() {
  const [hash, setHash] = useState(window.location.hash)
  useEffect(() => {
    const on = () => setHash(window.location.hash)
    window.addEventListener('hashchange', on)
    return () => window.removeEventListener('hashchange', on)
  }, [])
  const m = hash.match(/^#\/meeting\/(.+)$/)
  return m ? { name: 'meeting', id: m[1] } : { name: 'list' }
}

const hueFor = (meeting, speaker) =>
  SPEAKER_HUES[Math.max(0, meeting.speakers.indexOf(speaker)) % SPEAKER_HUES.length]

/* ---------- search ---------- */
const STOP = new Set('the a an and or of to in on for is are was were what who when did do does we you it that this with about from how'.split(' '))
const terms = (q) => q.toLowerCase().split(/\W+/).filter((w) => w && !STOP.has(w))

function scoreLines(meeting, q) {
  const ts = terms(q)
  if (!ts.length) return []
  return meeting.transcript
    .map((l) => {
      const low = l.x.toLowerCase()
      return { line: l, score: ts.reduce((n, t) => n + (low.includes(t) ? 1 : 0), 0) }
    })
    .filter((r) => r.score > 0)
    .sort((a, b) => b.score - a.score || a.line.t - b.line.t)
}

// For server rows the list only carries the flat transcript text, so show the words around the first match.
function snippet(text, q) {
  const low = text.toLowerCase()
  const hit = terms(q).map((t) => low.indexOf(t)).filter((i) => i >= 0).sort((a, b) => a - b)[0]
  if (hit === undefined) return null
  const a = Math.max(0, text.lastIndexOf(' ', Math.max(0, hit - 70)))
  return (a > 0 ? '…' : '') + text.slice(a, hit + 110).trim() + '…'
}

function Mark({ text, q }) {
  const ts = terms(q)
  if (!ts.length) return text
  const re = new RegExp(`(${ts.map((t) => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('|')})`, 'gi')
  return text.split(re).map((p, i) => (i % 2 ? <mark key={i}>{p}</mark> : p))
}

