/* ---------- upload ---------- */
const ACCEPT = '.wav,.mp3,.m4a,.mp4,.webm,.ogg,.flac,.aac,.mov,.mkv,audio/*,video/*'

function Upload({ online, onDone }) {
  const input = useRef()
  const [state, setState] = useState(null) // {name, progress} | {error}
  const [drag, setDrag] = useState(false)
  const send = async (file) => {
    if (!file) return
    setState({ name: file.name, progress: 0 })
    try {
      const m = await api.upload(file, '', (p) => setState({ name: file.name, progress: p }))
      setState(null)
      onDone(m)
    } catch (e) {
      setState({ error: e.message })
    }
  }
  useEffect(() => {
    // Dropping a file anywhere on the list page uploads it.
    const over = (e) => { if (online && e.dataTransfer?.types?.includes('Files')) { e.preventDefault(); setDrag(true) } }
    const leave = (e) => { if (!e.relatedTarget) setDrag(false) }
    const drop = (e) => { if (!online) return; e.preventDefault(); setDrag(false); send(e.dataTransfer.files[0]) }
    window.addEventListener('dragover', over); window.addEventListener('dragleave', leave); window.addEventListener('drop', drop)
    return () => { window.removeEventListener('dragover', over); window.removeEventListener('dragleave', leave); window.removeEventListener('drop', drop) }
  })
  return (
    <>
      <button className="primary" disabled={!online || (state && !state.error)} onClick={() => input.current.click()}>
        Upload recording
      </button>
      <input ref={input} type="file" accept={ACCEPT} hidden onChange={(e) => { send(e.target.files[0]); e.target.value = '' }} />
      {state && (
        <div className={state.error ? 'upload-bar err' : 'upload-bar'} role="status">
          {state.error ? (
            <>
              <span>{state.error}</span>
              <button className="link" onClick={() => setState(null)}>Dismiss</button>
            </>
          ) : (
            <>
              <span>Uploading {state.name}</span>
              <span className="meter"><i style={{ width: `${Math.round(state.progress * 100)}%` }} /></span>
              <b>{Math.round(state.progress * 100)}%</b>
            </>
          )}
        </div>
      )}
      {drag && <div className="dropzone" aria-hidden="true"><p>Drop a recording to transcribe it</p></div>}
    </>
  )
}

/* ---------- list ---------- */
function Faces({ m }) {
  return (
    <div className="faces" aria-label={m.speakers.join(', ')}>
      {m.speakers.slice(0, 4).map((s) => (
        <span key={s} className="face" style={{ background: hueFor(m, s) }} title={s}>{initials(s)}</span>
      ))}
    </div>
