}

function MeetingRow({ m, q }) {
  const hits = q && !m.remote ? scoreLines(m, q) : []
  const snip = q && m.remote ? snippet(m.search || '', q) : null
  const open = m.remote ? m.open_actions : m.actions.filter((a) => !a.done).length
  const working = busy(m.stage)
  return (
    <a className="row" href={`#/meeting/${m.id}`}>
      <div className="row-main">
        <h3>
          {m.title}
          {!m.remote && <span className="tag">Sample</span>}
        </h3>
        <p className="row-meta">
          {fmtDate(m.date)}
          {m.duration ? ` · ${fmtMinutes(m.duration)}` : ''}
        </p>
        {hits[0] && (
          <p className="row-hit">
            <span className="clock">{fmtClock(hits[0].line.t)}</span>
            <span><Mark text={hits[0].line.x} q={q} /></span>
          </p>
        )}
        {snip && <p className="row-hit"><span><Mark text={snip} q={q} /></span></p>}
      </div>
      <div className="row-side">
        {working ? (
          <span className="pill work"><span className="spin" aria-hidden="true" />{STAGES[m.stage]}</span>
        ) : m.stage === 'failed' ? (
          <span className="pill bad">Failed</span>
        ) : (
          <>
            <Faces m={m} />
            <span className={open ? 'pill open' : 'pill'}>{open ? `${open} open` : 'All done'}</span>
          </>
        )}
      </div>
    </a>
  )
}

function List({ remote, online, refresh }) {
  const [tab, setTab] = useState('mine')
  const [q, setQ] = useState('')
  const all = useMemo(() => {
    const rows = remote.map((r) => ({ ...r, remote: true, speakers: (r.speakers || []).map((s) => r.names?.[s] || s) }))
    return [...rows, ...samples].sort((a, b) => b.date.localeCompare(a.date))
  }, [remote])
  const shown = useMemo(() => {
    if (!q) return all.filter((m) => m.scope === tab)
    const low = q.toLowerCase()
    return all.filter((m) =>
      m.title.toLowerCase().includes(low) ||
      (m.remote ? snippet(m.search || '', q) : scoreLines(m, q).length))
  }, [all, tab, q])
  return (
    <main className="page">
      <header className="page-head">
        <h1>Meetings</h1>
        <div className="head-actions">
          <label className="search">
            <span className="sr">Search all meetings</span>
            <input type="search" placeholder="Search every transcript" value={q} onChange={(e) => setQ(e.target.value)} />
          </label>
          <Upload online={online} onDone={refresh} />
        </div>
      </header>
      {!q && (
        <div className="tabs" role="tablist">
          {[['mine', 'My calls'], ['team', 'Team calls']].map(([k, label]) => (
            <button key={k} role="tab" aria-selected={tab === k} className={tab === k ? 'tab on' : 'tab'} onClick={() => setTab(k)}>
              {label}
            </button>
          ))}
        </div>
      )}
      {q && <p className="search-note">{shown.length} of {all.length} meetings match “{q}”</p>}
      <div className="rows">
        {shown.map((m) => <MeetingRow key={m.id} m={m} q={q} />)}
        {!shown.length && q && <p className="empty">No meeting mentions “{q}”. Try a different word.</p>}
        {!shown.length && !q && <p className="empty">No team calls yet. Recordings you upload appear under My calls.</p>}
      </div>
    </main>
  )
}

/* ---------- players ---------- */
// Sample meetings have no audio, so a timer stands in for playback.
function useMockPlayer(dur) {
  const [now, setNow] = useState(0)
  const [playing, setPlaying] = useState(false)
  useEffect(() => {
    if (!playing) return
    const t = setInterval(() => setNow((n) => (n + 1 >= dur ? (setPlaying(false), dur) : n + 1)), 1000)
    return () => clearInterval(t)
  }, [playing, dur])
  return { now, dur, playing, real: false, toggle: () => setPlaying((p) => !p), seek: (t) => { setNow(t); setPlaying(true) } }
}

function useAudioPlayer(src, fallbackDur) {
  const el = useRef()
  const [now, setNow] = useState(0)
  const [dur, setDur] = useState(fallbackDur || 1)
  const [playing, setPlaying] = useState(false)
  const audio = (
    <audio
      ref={el}
      src={src}
      preload="metadata"
      onTimeUpdate={(e) => setNow(e.currentTarget.currentTime)}
      onLoadedMetadata={(e) => isFinite(e.currentTarget.duration) && setDur(e.currentTarget.duration)}
      onPlay={() => setPlaying(true)}
      onPause={() => setPlaying(false)}
    />
  )
  return {
    now, dur, playing, real: true, audio,
    toggle: () => (el.current.paused ? el.current.play() : el.current.pause()),
    seek: (t) => { el.current.currentTime = t; setNow(t); el.current.play() },
  }
}

/* ---------- detail ---------- */
function Legend({ meeting, share, total, onRename }) {
  const [editing, setEditing] = useState(null)
  const [value, setValue] = useState('')
  return (
    <ul className="legend">
      {meeting.speakers.map((s, i) => {
        const label = meeting.labels?.[i]
        const pct = total ? Math.round(((share[s] || 0) / total) * 100) : 0
        if (onRename && editing === label) {
          return (
            <li key={s}>
              <form onSubmit={(e) => { e.preventDefault(); onRename(label, value); setEditing(null) }} className="rename">
                <i style={{ background: hueFor(meeting, s) }} />
                <input autoFocus value={value} onChange={(e) => setValue(e.target.value)} aria-label={`Name for ${label}`}
                  onBlur={() => setEditing(null)} onKeyDown={(e) => e.key === 'Escape' && setEditing(null)} />
              </form>
            </li>
          )
        }
        return (
          <li key={s}>
            <i style={{ background: hueFor(meeting, s) }} />
            {onRename ? (
              <button className="link" title="Rename speaker" onClick={() => { setEditing(label); setValue(meeting.names[label] || '') }}>{s}</button>
            ) : s}
            <b>{pct}%</b>
          </li>
        )
      })}
    </ul>
  )
}

function TalkStrip({ meeting, player, onRename }) {
  const { dur, now, seek } = player
  const segs = meeting.transcript.map((l, i) => {
    const end = l.end ?? meeting.transcript[i + 1]?.t ?? dur
    return { l, left: (l.t / dur) * 100, width: (Math.max(0, end - l.t) / dur) * 100 }
  })
  const share = {}
  segs.forEach((s) => { share[s.l.s] = (share[s.l.s] || 0) + s.width })
  const total = Object.values(share).reduce((a, b) => a + b, 0)
  return (
    <div className="strip-wrap">
      <div
        className="strip"
        role="slider"
        tabIndex={0}
        aria-label="Recording position"
        aria-valuemin={0}
        aria-valuemax={Math.round(dur)}
        aria-valuenow={Math.round(now)}
        aria-valuetext={fmtClock(now)}
        onClick={(e) => {
          const r = e.currentTarget.getBoundingClientRect()
          seek(((e.clientX - r.left) / r.width) * dur)
        }}
        onKeyDown={(e) => {
          if (e.key === 'ArrowRight') seek(Math.min(dur, now + 5))
          if (e.key === 'ArrowLeft') seek(Math.max(0, now - 5))
        }}
      >
        {segs.map((s, i) => (
          <span key={i} className="seg" style={{ left: `${s.left}%`, width: `${s.width}%`, background: hueFor(meeting, s.l.s) }} />
        ))}
        <span className="playhead" style={{ left: `${Math.min(100, (now / dur) * 100)}%` }} />
      </div>
      <Legend meeting={meeting} share={share} total={total} onRename={onRename} />
    </div>
  )
}

function Transcript({ meeting, now, onSeek, q }) {
  const active = meeting.transcript.reduce((a, l, i) => (l.t <= now ? i : a), -1)
  const box = useRef()
  const refs = useRef([])
  const follow = useRef(true)
  useEffect(() => {
    const el = refs.current[active]
    if (!follow.current || !el || !box.current) return
    const b = box.current
    if (el.offsetTop < b.scrollTop || el.offsetTop + el.offsetHeight > b.scrollTop + b.clientHeight) {
      b.scrollTo({ top: el.offsetTop - b.clientHeight / 3, behavior: 'smooth' })
    }
  }, [active])
  return (
    <ol ref={box} className="transcript" onWheel={() => (follow.current = false)} onTouchMove={() => (follow.current = false)}>
      {meeting.transcript.map((l, i) => {
        const dim = q && !terms(q).some((t) => l.x.toLowerCase().includes(t))
        return (
          <li key={i} ref={(el) => (refs.current[i] = el)} className={`line${i === active ? ' active' : ''}${dim ? ' dim' : ''}`}>
            <button className="stamp" onClick={() => { follow.current = true; onSeek(l.t) }} aria-label={`Play from ${fmtClock(l.t)}`}>
              {fmtClock(l.t)}
            </button>
            <div>
              <span className="who" style={{ color: hueFor(meeting, l.s) }}>{l.s}</span>
              <p><Mark text={l.x} q={q} /></p>
            </div>
          </li>
        )
      })}
    </ol>
  )
}

function Summary({ s }) {
  return (
    <div className="stack">
      <section>
        <h2>Overview</h2>
        <p className="lead">{s.overview || 'No overview was written for this meeting.'}</p>
      </section>
      {s.points.length > 0 && (
        <section>
          <h2>Key points</h2>
          <ul className="bullets">{s.points.map((p) => <li key={p}>{p}</li>)}</ul>
        </section>
      )}
      <section>
        <h2>Decisions</h2>
        {s.decisions.length ? (
          <ul className="bullets decisions">{s.decisions.map((p) => <li key={p}>{p}</li>)}</ul>
        ) : (
          <p className="muted">No decisions were recorded.</p>
        )}
      </section>
    </div>
  )
}

function Actions({ meeting, onSeek, onToggle }) {
  const key = `sounding:actions:${meeting.id}`
  const initial = () => Object.fromEntries(meeting.actions.map((a) => [a.id, a.done]))
  const [local, setLocal] = useState(() => {
    if (meeting.remote) return initial()
    try { return JSON.parse(localStorage.getItem(key)) ?? initial() } catch { return initial() }
  })
  useEffect(() => { if (meeting.remote) setLocal(initial()) }, [meeting]) // eslint-disable-line react-hooks/exhaustive-deps
  const toggle = (id) => {
    const next = { ...local, [id]: !local[id] }
    setLocal(next)
    if (meeting.remote) onToggle({ [id]: next[id] })
    else try { localStorage.setItem(key, JSON.stringify(next)) } catch { /* storage unavailable */ }
  }
  if (!meeting.actions.length) return <p className="muted">No action items were found in this meeting.</p>
  return (
    <ul className="actions">
      {meeting.actions.map((a) => (
        <li key={a.id} className={local[a.id] ? 'done' : ''}>
          <label>
            <input type="checkbox" checked={!!local[a.id]} onChange={() => toggle(a.id)} />
            <span className="box" aria-hidden="true" />
            <span className="atext">{a.text}</span>
          </label>
          <span className="ameta">
            {a.owner ? (
              <><span className="face sm" style={{ background: hueFor(meeting, a.owner) }}>{initials(a.owner)}</span>{a.owner}</>
            ) : 'Unassigned'}
            {a.due && <> · due {a.due}</>}
            {a.t != null && <> · <button className="link clock" onClick={() => onSeek(a.t)}>{fmtClock(a.t)}</button></>}
          </span>
        </li>
      ))}
    </ul>
  )
}

// Turns "[12:34]" in a model answer into buttons that jump the player.
function Cited({ text, onSeek }) {
  return text.split(/(\[\d+:\d{2}\])/g).map((p, i) => {
    const m = p.match(/^\[(\d+):(\d{2})\]$/)
    return m ? (
      <button key={i} className="link clock" onClick={() => onSeek(+m[1] * 60 + +m[2])}>{m[1]}:{m[2]}</button>
    ) : p
  })
}

function localAnswer(meeting, question) {
  const lower = question.toLowerCase()
  if (/action|todo|follow.?up|owe|task/.test(lower))
    return { text: 'Open action items:', items: meeting.actions.filter((a) => !a.done).map((a) => `${a.owner}: ${a.text} (due ${a.due})`) }
  if (/decid|decision|agree/.test(lower)) return { text: 'Decisions from this meeting:', items: meeting.summary.decisions }
  if (/summar|overview|about/.test(lower)) return { text: meeting.summary.overview, items: [] }
  const hits = scoreLines(meeting, question).slice(0, 2)
  return hits.length
    ? { text: 'Closest moments in the transcript:', cites: hits.map((h) => h.line) }
    : { text: 'Nothing in this meeting matches that. Try a specific word from the conversation.', items: [] }
}

function Ask({ meeting, onSeek, thread, setThread }) {
  const [q, setQ] = useState('')
  const [pending, setPending] = useState(false)
  const ask = async (text) => {
    const question = text.trim()
    if (!question || pending) return
    setQ('')
    if (!meeting.remote) return setThread((t) => [...t, { question, answer: localAnswer(meeting, question) }])
    setPending(question)
    try {
      const { answer } = await api.ask(meeting.id, question)
      setThread((t) => [...t, { question, answer: { text: answer, model: true } }])
    } catch (e) {
      setThread((t) => [...t, { question, answer: { text: e.message, error: true } }])
    } finally {
      setPending(false)
    }
  }
  const suggestions = meeting.remote
    ? ['What did we decide?', 'What are the open questions?', 'Summarize what each speaker wanted']
    : ['What did we decide?', 'What are the action items?', 'Who mentioned renewals?']
  return (
    <div className="ask">
      <div className="thread" aria-live="polite">
        {!thread.length && !pending && (
          <div className="suggest">
            <p>{meeting.remote ? 'Ask anything about this meeting. Answers link to the moment in the recording.' : 'Ask about this meeting.'}</p>
            {suggestions.map((s) => <button key={s} onClick={() => ask(s)}>{s}</button>)}
          </div>
        )}
        {thread.map((m, i) => (
          <div key={i} className="qa">
            <p className="q">{m.question}</p>
            <div className={m.answer.error ? 'a err' : 'a'}>
              <p>{m.answer.model ? <Cited text={m.answer.text} onSeek={onSeek} /> : m.answer.text}</p>
              {m.answer.items?.length > 0 && <ul className="bullets">{m.answer.items.map((x) => <li key={x}>{x}</li>)}</ul>}
              {m.answer.cites?.map((c, j) => (
                <button key={j} className="cite" onClick={() => onSeek(c.t)}>
                  <span className="clock">{fmtClock(c.t)}</span>
                  <span><b>{c.s}:</b> {c.x}</span>
                </button>
              ))}
            </div>
          </div>
        ))}
        {pending && (
          <div className="qa">
            <p className="q">{pending}</p>
            <div className="a thinking"><span className="spin" aria-hidden="true" /> Reading the transcript</div>
          </div>
        )}
      </div>
      <form onSubmit={(e) => { e.preventDefault(); ask(q) }} className="ask-form">
        <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Ask about this meeting" aria-label="Ask about this meeting" />
        <button type="submit" disabled={!!pending}>Ask</button>
      </form>
    </div>
  )
}

function MeetingView({ meeting, player, onRename, onToggle, onDelete }) {
  const [tab, setTab] = useState('summary')
  const [find, setFind] = useState('')
  const [thread, setThread] = useState([])
  const open = meeting.actions.filter((a) => !a.done).length
  return (
    <main className="detail">
      <header className="d-head">
        <a className="back" href="#/">Meetings</a>
        <div className="title-row">
          <h1>{meeting.title}</h1>
          {onDelete && <button className="link danger" onClick={onDelete}>Delete meeting</button>}
        </div>
        <p className="row-meta">
          {fmtDate(meeting.date)} · {fmtMinutes(meeting.duration)} · {meeting.speakers.join(', ')}
        </p>
      </header>

      <div className="d-grid">
        <section className="left" aria-label="Recording and transcript">
          {player.audio}
          <div className="player">
            <button className="play" onClick={player.toggle} aria-label={player.playing ? 'Pause' : 'Play'}>
              {player.playing
                ? <svg viewBox="0 0 24 24" width="18" height="18"><path d="M7 5h4v14H7zM13 5h4v14h-4z" fill="currentColor" /></svg>
                : <svg viewBox="0 0 24 24" width="18" height="18"><path d="M8 5v14l11-7z" fill="currentColor" /></svg>}
            </button>
            <span className="time">{fmtClock(player.now)} <span>/ {fmtClock(player.dur)}</span></span>
            <span className="demo">
              {player.real ? (onRename ? 'Click a speaker to name them' : '') : 'Sample meeting: no audio'}
            </span>
          </div>
          <TalkStrip meeting={meeting} player={player} onRename={onRename} />
          <label className="find">
            <span className="sr">Find in transcript</span>
            <input type="search" placeholder="Find in transcript" value={find} onChange={(e) => setFind(e.target.value)} />
          </label>
          <Transcript meeting={meeting} now={player.now} onSeek={player.seek} q={find} />
        </section>

        <aside className="right" aria-label="Meeting notes">
          <div className="tabs" role="tablist">
            {[['summary', 'Summary'], ['actions', `Action items${open ? ` (${open})` : ''}`], ['ask', 'Ask']].map(([k, label]) => (
              <button key={k} role="tab" aria-selected={tab === k} className={tab === k ? 'tab on' : 'tab'} onClick={() => setTab(k)}>{label}</button>
            ))}
          </div>
          <div className="panel">
            {tab === 'summary' && <Summary s={meeting.summary} />}
            {tab === 'actions' && <Actions meeting={meeting} onSeek={player.seek} onToggle={onToggle} />}
            {tab === 'ask' && <Ask meeting={meeting} onSeek={player.seek} thread={thread} setThread={setThread} />}
          </div>
          {meeting.timings && (
            <p className="provenance">
              Speakers found in {meeting.timings.speakers}s, transcribed in {meeting.timings.transcribe}s,
              notes written in {meeting.timings.summarize}s on your GPU server.
            </p>
          )}
        </aside>
      </div>
    </main>
  )
}

function SampleMeeting({ meeting }) {
  // Sample transcripts are short excerpts, so the mock player spans the excerpt, not the full call length.
  const player = useMockPlayer(meeting.transcript[meeting.transcript.length - 1].t + 25)
  return <MeetingView meeting={meeting} player={player} />
}

function RemoteReady({ raw, setRaw, refreshList }) {
  const meeting = useMemo(() => adapt(raw), [raw])
  const player = useAudioPlayer(api.audioUrl(raw.id), raw.duration)
  const save = async (body) => {
    try { setRaw(await api.patch(raw.id, body)) } catch (e) { alert(e.message) }
  }
  const onRename = (label, name) => save({ names: { ...raw.names, [label]: name.trim() || undefined } })
  const onDelete = async () => {
    if (!confirm(`Delete “${raw.title}”? The recording, transcript and notes are removed from the server.`)) return
    await api.remove(raw.id)
    refreshList()
    window.location.hash = '#/'
  }
  return <MeetingView meeting={meeting} player={player} onRename={onRename} onToggle={(done) => save({ done })} onDelete={onDelete} />
}

function RemoteMeeting({ id, refreshList }) {
  const [raw, setRaw] = useState(null)
  const [error, setError] = useState(null)
  useEffect(() => {
    let stop = false, timer
    const load = async () => {
      try {
        const m = await api.get(id)
        if (stop) return
        setRaw(m)
        if (busy(m.stage)) timer = setTimeout(load, 2500)
      } catch (e) {
        if (!stop) setError(e.message)
      }
    }
    setRaw(null); setError(null); load()
    return () => { stop = true; clearTimeout(timer) }
  }, [id])

  if (error) return <main className="page"><p className="empty">{error}. <a href="#/">Back to meetings</a></p></main>
  if (!raw) return <main className="page"><p className="empty"><span className="spin" aria-hidden="true" /> Loading meeting</p></main>
  if (raw.stage !== 'done') return <Processing raw={raw} refreshList={refreshList} />
  return <RemoteReady raw={raw} setRaw={setRaw} refreshList={refreshList} />
}

const ORDER = ['queued', 'converting', 'speakers', 'transcribing', 'summarizing']
function Processing({ raw, refreshList }) {
  const at = ORDER.indexOf(raw.stage)
  const del = async () => { await api.remove(raw.id); refreshList(); window.location.hash = '#/' }
  return (
    <main className="page">
      <a className="back" href="#/">Meetings</a>
      <h1 className="proc-title">{raw.title}</h1>
      {raw.stage === 'failed' ? (
        <div className="proc">
          <p>This recording couldn’t be processed.</p>
          <p className="muted">{raw.error}</p>
          <button className="primary" onClick={del}>Delete and try another file</button>
        </div>
      ) : (
        <ol className="proc steps">
          {ORDER.slice(1).map((s, i) => (
            <li key={s} className={i + 1 < at ? 'done' : i + 1 === at ? 'now' : ''}>
              {i + 1 === at && <span className="spin" aria-hidden="true" />}
              {STAGES[s]}
            </li>
          ))}
          {at === 0 && <li className="now"><span className="spin" aria-hidden="true" />Waiting for the recording ahead of it</li>}
        </ol>
      )}
    </main>
  )
}

export default function App() {
  const route = useHashRoute()
  const { rows, online, refresh } = useRemoteList()
  const sample = route.name === 'meeting' && samples.find((m) => m.id === route.id)
  return (
    <div className="shell">
      <Rail route={route} online={online} />
      {route.name === 'list' && <List remote={rows} online={online} refresh={refresh} />}
      {sample && <SampleMeeting key={sample.id} meeting={sample} />}
      {route.name === 'meeting' && !sample && <RemoteMeeting key={route.id} id={route.id} refreshList={refresh} />}
    </div>
  )
}

