def connect():
    c = sqlite3.connect(DB_PATH, timeout=30)
    c.row_factory = sqlite3.Row
    c.execute("PRAGMA journal_mode=WAL")
    c.execute("PRAGMA [ssh-key]=ON")
    return c


def init():
    os.makedirs(MEDIA, exist_ok=True)
    with connect() as c:
        c.executescript(SCHEMA)


def row(r):
    if r is None:
        return None
    d = dict(r)
    for k in JSON_COLS & d.keys():
        if isinstance(d[k], str):
            d[k] = json.loads(d[k])
    return d


def one(sql, *args):
    with connect() as c:
        return row(c.execute(sql, args).fetchone())


def many(sql, *args):
    with connect() as c:
        return [row(r) for r in c.execute(sql, args).fetchall()]


def run(sql, *args):
    with connect() as c:
        return c.execute(sql, args).rowcount


def enc(v):
    return json.dumps(v) if isinstance(v, (dict, list)) else v


def insert(table, **vals):
    keys = list(vals)
    with connect() as c:
        c.execute(f"INSERT INTO {table} ({','.join(keys)}) VALUES ({','.join('?' * len(keys))})", [enc(vals[k]) for k in keys])
    return vals


def update(table, key, key_val, **vals):
    if not vals:
        return 0
    sets = ",".join(f"{k}=?" for k in vals)
    with connect() as c:
        return c.execute(f"UPDATE {table} SET {sets} WHERE {key}=?", [enc(v) for v in vals.values()] + [key_val]).rowcount


def new_id(n=10):
    return secrets.token_hex(n // 2 + 1)[:n]


def now():
    return time.time()
