def sha(s):
    return hashlib.sha256(s.encode()).hexdigest()


# ---------- sessions ----------
def create_session(user_id):
    tok = secrets.token_urlsafe(32)
    db.insert("sessions", token_hash=sha(tok), user_id=user_id, expires=time.time() + SESSION_DAYS * 86400)
