    if not u or not auth.check_pw(body.password, u["pw_hash"]):
        _attempts[ip].append(time.time())
        raise HTTPException(401, "That email and password don't match an account.")
    set_cookie(req, resp, auth.create_session(u["id"]))
    return me_payload(u)


