    db.run("DELETE FROM jobs WHERE ref=? AND state='queued'", mid)
    db.run("DELETE FROM meetings WHERE id=?", mid)
    shutil.rmtree(jobs.mdir(mid), ignore_errors=True)
    return {"deleted": mid}


