            d = a.split("@")[-1].lower()
            if "@" not in a or d in own or d in CONSUMER:
                continue
            c = by.setdefault(d, dict(domain=d, meetings=set(), people=set(), last=m["date"]))
            c["meetings"].add(m["id"]); c["people"].add(a)
            c["last"] = max(c["last"], m["date"])
