// Wraps an async action with a busy flag and toasts errors.
export function useAction(toast) {
  const [busyKey, setBusy] = useState(null)
  const run = useCallback(async (key, fn, okText) => {
    setBusy(key)
    try {
      const r = await fn()
      if (okText) toast?.(okText)
      return r
