body { margin: 0; background: var(--paper); color: var(--ink); font-size: 15px; line-height: 1.5; }
a { color: inherit; }
button, input, select, textarea { font: inherit; color: inherit; }
button { cursor: pointer; }
button:disabled { cursor: not-allowed; }
:focus-visible { outline: 2px solid var(--teal); outline-offset: 2px; }
.sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
mark { background: var(--hl); color: inherit; border-radius: 3px; padding: 0 1px; }
h1 { font-size: 28px; line-height: 1.15; margin: 0; letter-spacing: -0.02em; font-weight: 700; }
h2 { font-size: 15px; font-weight: 700; margin: 0 0 8px; }
h3 { margin: 0; }
hr { border: 0; border-top: 1px solid var(--line); margin: 10px 0; }
.muted { color: var(--ink-2); margin: 0; }
.small { font-size: 13px; }

/* ---------- buttons & inputs ---------- */
.primary, .secondary, .danger-btn, .as-btn {
  border-radius: 999px; font-weight: 600; padding: 8px 16px; white-space: nowrap; border: 1px solid transparent;
  display: inline-flex; align-items: center; gap: 8px; text-decoration: none; justify-content: center;
}
.primary { background: var(--teal); color: var(--paper); }
.secondary { background: var(--panel); border-color: var(--line); color: var(--ink); }
.secondary:hover:not(:disabled) { border-color: var(--teal); }
.danger-btn { background: var(--bad-bg); color: var(--bad); }
.primary:disabled, .secondary:disabled, .danger-btn:disabled { opacity: 0.5; }
.small-btn { padding: 4px 12px; font-size: 13.5px; }
.link { background: none; border: 0; padding: 0; color: inherit; text-decoration: underline; text-decoration-color: var(--line); text-underline-offset: 3px; }
.link:hover { text-decoration-color: currentColor; }
.link.clock, .clock { color: var(--teal); text-decoration: none; font-weight: 600; font-variant-numeric: tabular-nums; }
.link.danger, .danger { color: var(--bad); }
.icon-btn { background: none; border: 0; border-radius: 8px; width: 34px; height: 34px; display: inline-grid; place-items: center; color: var(--ink-2); position: relative; }
.icon-btn:hover { background: var(--teal-soft); color: var(--ink); }
input:not([type=checkbox]):not([type=radio]):not([type=range]), select, textarea {
  width: 100%; padding: 9px 12px; border: 1px solid var(--line); border-radius: 8px; background: var(--panel);
}
textarea { resize: vertical; min-height: 80px; }
input:disabled { opacity: 0.7; }
.field { display: flex; flex-direction: column; gap: 5px; min-width: 0; }
.field-label { font-weight: 600; font-size: 14px; }
.field-hint { font-size: 12.5px; color: var(--ink-2); }
.stack-form { display: flex; flex-direction: column; gap: 14px; }
.grid2 { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }
.form-error { color: var(--bad); margin: 0; }
.row-gap { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }

/* ---------- shell ---------- */
.shell { display: grid; grid-template-columns: 224px minmax(0, 1fr); min-height: 100vh; }
.shell > * { min-width: 0; }
.rail { position: sticky; top: 0; height: 100vh; overflow-y: auto; padding: 20px 12px; border-right: 1px solid var(--line); display: flex; flex-direction: column; gap: 2px; }
.brand { display: flex; align-items: center; gap: 10px; font-weight: 700; font-size: 18px; text-decoration: none; letter-spacing: -0.01em; margin: 0 8px; }
.brand-mark { width: 22px; height: 22px; border-radius: 50%; flex: none;
  background: radial-gradient(circle at 50% 35%, var(--teal) 0 30%, transparent 31%), conic-gradient(from 200deg, var(--teal), #3b5bdb, var(--teal));
  box-shadow: inset 0 0 0 3px var(--paper); }
.org-name { margin: 2px 8px 14px 40px; font-size: 13px; color: var(--ink-2); }
.rail-link { display: flex; align-items: center; gap: 10px; padding: 7px 10px; border-radius: 8px; text-decoration: none; color: var(--ink-2); font-weight: 500; }
.rail-link:hover { background: var(--panel); color: var(--ink); }
.rail-link.on { background: var(--teal-soft); color: var(--teal); font-weight: 600; }
.main-col { display: flex; flex-direction: column; min-width: 0; }
.topbar { display: flex; align-items: center; gap: 12px; padding: 12px 32px; border-bottom: 1px solid var(--line); position: sticky; top: 0; background: var(--paper); z-index: 5; }
.global-search { flex: 1; max-width: 520px; }
.global-search input { border-radius: 999px; padding: 8px 16px; }
.topbar .primary { margin-left: auto; }
.avatar-btn { background: none; border: 0; padding: 0; border-radius: 50%; }
.bell .badge { position: absolute; top: 2px; right: 2px; min-width: 16px; height: 16px; border-radius: 8px; background: var(--bad); color: #fff; font-size: 10px; font-weight: 700; display: grid; place-items: center; padding: 0 3px; }

.page { padding: 28px 32px 60px; width: 100%; max-width: 1100px; }
.page.wide { max-width: none; }
.page-head { display: flex; align-items: flex-end; justify-content: space-between; gap: 16px; flex-wrap: wrap; margin-bottom: 18px; }
.page-sub { margin: 6px 0 0; color: var(--ink-2); max-width: 70ch; }
.head-actions { display: flex; gap: 10px; align-items: center; flex-wrap: wrap; }
.back { color: var(--ink-2); text-decoration: none; font-size: 14px; }
.back::before { content: '‹ '; }

/* ---------- tabs ---------- */
.tabs { display: flex; gap: 22px; border-bottom: 1px solid var(--line); margin-bottom: 14px; overflow-x: auto; }
.tab { background: none; border: 0; padding: 8px 0 10px; color: var(--ink-2); font-weight: 500; border-bottom: 2px solid transparent; margin-bottom: -1px; white-space: nowrap; }
.tab.on { color: var(--ink); font-weight: 600; border-bottom-color: var(--teal); }

/* ---------- avatars, tags, pills ---------- */
.avatar { border-radius: 50%; display: inline-grid; place-items: center; color: #fff; font-weight: 600; flex: none; line-height: 1; }
.faces { display: inline-flex; }
.faces .avatar { border: 2px solid var(--paper); margin-left: -6px; }
.faces .avatar:first-child { margin-left: 0; }
.avatar.more { background: var(--line); color: var(--ink-2); width: 28px; height: 28px; font-size: 11px; }
.tag { font-size: 12px; font-weight: 500; color: var(--ink-2); border: 1px solid var(--line); border-radius: 999px; padding: 1px 9px; white-space: nowrap; }
.tag.company { color: var(--teal); border-color: color-mix(in srgb, var(--teal) 40%, var(--line)); }
.tag.quiet { border-style: dashed; }
.pill { font-size: 12.5px; padding: 3px 10px; border-radius: 999px; background: var(--teal-soft); color: var(--teal); font-weight: 600; white-space: nowrap; display: inline-flex; align-items: center; gap: 7px; }
.pill.open { background: var(--warn-bg); color: var(--warn); }
.pill.bad { background: var(--bad-bg); color: var(--bad); }
.pill.work { background: var(--panel); color: var(--ink-2); border: 1px solid var(--line); }

/* ---------- meeting rows ---------- */
.mrows { display: flex; flex-direction: column; }
.mrow { display: flex; align-items: center; border-bottom: 1px solid var(--line); }
.mrow-link { flex: 1; min-width: 0; display: flex; justify-content: space-between; gap: 20px; padding: 16px 12px; margin: 0 -12px; text-decoration: none; border-radius: 8px; }
.mrow-link:hover { background: var(--panel); }
.mrow h3 { font-size: 16.5px; font-weight: 600; }
.mrow-meta { margin: 2px 0 0; color: var(--ink-2); font-size: 14px; }
.mrow-tags { display: flex; gap: 6px; flex-wrap: wrap; margin-top: 6px; }
.mrow-tags:empty { display: none; }
.mrow-overview { margin: 8px 0 0; color: var(--ink-2); font-size: 14px; max-width: 80ch; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.mrow-side { display: flex; align-items: center; gap: 14px; flex-shrink: 0; }
.mrow-actions { padding-left: 12px; }

/* ---------- feedback ---------- */
.spin-wrap { display: inline-flex; align-items: center; gap: 8px; }
.spin { display: inline-block; width: 13px; height: 13px; border: 2px solid var(--line); border-top-color: var(--teal); border-radius: 50%; animation: spin 0.8s linear infinite; flex: none; }
@keyframes spin { to { transform: rotate(360deg); } }
@media (prefers-reduced-motion: reduce) { .spin { animation-duration: 3s; } }
.loading { padding: 48px 32px; color: var(--ink-2); display: flex; justify-content: center; }
.empty { padding: 40px 0; max-width: 520px; display: flex; flex-direction: column; gap: 8px; align-items: flex-start; }
.empty-title { font-weight: 600; font-size: 16px; margin: 0; }
.error-note { display: flex; gap: 12px; align-items: center; justify-content: space-between; background: var(--bad-bg); color: var(--bad); border-radius: var(--radius); padding: 10px 14px; margin: 10px 0; }
.toasts { position: fixed; bottom: 20px; left: 50%; transform: translateX(-50%); display: flex; flex-direction: column; gap: 8px; z-index: 50; align-items: center; }
.toast { background: var(--ink); color: var(--paper); padding: 10px 16px; border-radius: 10px; box-shadow: var(--shadow); max-width: 90vw; }
.toast.error { background: var(--bad); color: #fff; }
.meter { display: block; height: 6px; background: var(--line); border-radius: 3px; overflow: hidden; }
.meter i { display: block; height: 100%; background: var(--teal); transition: width 0.2s; }

/* ---------- menus & modals ---------- */
.menu-wrap { position: relative; display: inline-flex; }
.menu { position: absolute; top: calc(100% + 6px); z-index: 30; background: var(--panel); border: 1px solid var(--line); border-radius: 10px; box-shadow: var(--shadow); padding: 6px; min-width: 200px; display: flex; flex-direction: column; }
.menu.right { right: 0; }
.menu.left { left: 0; }
.menu > button { background: none; border: 0; text-align: left; padding: 8px 10px; border-radius: 6px; white-space: nowrap; }
.menu > button:hover:not(:disabled) { background: var(--teal-soft); }
.menu > button.danger { color: var(--bad); }
.menu hr { margin: 4px 0; }
.scrim { position: fixed; inset: 0; z-index: 25; }
.notif { width: 360px; max-height: 70vh; overflow-y: auto; padding: 0; }
.notif-head { display: flex; justify-content: space-between; align-items: center; padding: 12px 14px; border-bottom: 1px solid var(--line); }
.notif-empty { padding: 16px 14px; }
.notif-item { display: flex; flex-direction: column; gap: 2px; text-align: left; background: none; border: 0; border-bottom: 1px solid var(--line); padding: 10px 14px; }
.notif-item:hover { background: var(--teal-soft); }
.notif-item.unread { border-left: 3px solid var(--teal); font-weight: 500; }
.modal-back { position: fixed; inset: 0; background: rgba(8, 20, 24, 0.45); z-index: 40; display: grid; place-items: center; padding: 16px; }
.modal { background: var(--panel); border-radius: 14px; box-shadow: var(--shadow); width: 100%; max-width: 560px; max-height: 90vh; display: flex; flex-direction: column; }
.modal.wide { max-width: 820px; }
.modal-head { display: flex; justify-content: space-between; align-items: center; padding: 16px 20px 0; }
.modal-head h2 { font-size: 18px; margin: 0; }
.modal-body { padding: 16px 20px; overflow-y: auto; }
.modal-foot { display: flex; justify-content: flex-end; gap: 10px; padding: 12px 20px 16px; border-top: 1px solid var(--line); }
.drop { border: 2px dashed var(--line); border-radius: 12px; padding: 22px; display: flex; flex-direction: column; gap: 4px; align-items: center; text-align: center; cursor: pointer; }
.drop:hover, .drop.has { border-color: var(--teal); }

/* ---------- auth & public ---------- */
.auth { min-height: 100vh; display: grid; place-items: center; padding: 16px; }
.auth-card { width: 100%; max-width: 380px; display: flex; flex-direction: column; gap: 14px; }
.auth-brand { margin: 0 0 12px; }
.public { max-width: 1200px; margin: 0 auto; padding: 20px 24px 60px; }
.public-head { display: flex; justify-content: space-between; align-items: center; margin-bottom: 24px; }
.public h1 { margin-bottom: 4px; }
.public-grid { display: grid; grid-template-columns: minmax(0, 1.3fr) minmax(280px, 1fr); gap: 32px; margin-top: 20px; align-items: start; }
.public-media { width: 100%; border-radius: 10px; background: #000; }
.public-audio { width: 100%; }
.public-notes section { margin-top: 18px; }
.clip-note { background: var(--panel); border-left: 3px solid var(--teal); padding: 10px 14px; border-radius: 6px; }

/* ---------- shared transcript look (meeting page + public) ---------- */
.transcript { list-style: none; margin: 0; padding: 0 6px 0 0; max-height: 60vh; overflow-y: auto; }
.line { display: grid; grid-template-columns: 52px 1fr; gap: 6px; padding: 9px 10px; border-radius: 8px; border-left: 3px solid transparent; }
.line.active { background: var(--panel); border-left-color: var(--teal); }
.line p { margin: 2px 0 0; max-width: 68ch; }
.stamp { background: none; border: 0; padding: 1px 0 0; text-align: left; color: var(--teal); font-weight: 600; font-variant-numeric: tabular-nums; align-self: start; }
.who { font-weight: 600; font-size: 14px; }
.bullets { margin: 0; padding-left: 18px; display: flex; flex-direction: column; gap: 6px; max-width: 64ch; }

@media (max-width: 900px) {
  .shell { grid-template-columns: 1fr; grid-template-rows: auto 1fr; }
  .rail { position: static; height: auto; flex-direction: row; overflow-x: auto; align-items: center; padding: 10px 12px; border-right: 0; border-bottom: 1px solid var(--line); gap: 4px; }
  .rail hr, .org-name { display: none; }
  .brand { margin-right: 8px; }
  .rail-link { white-space: nowrap; }
  .topbar { padding: 10px 16px; flex-wrap: wrap; }
  .global-search { flex-basis: 100%; max-width: none; order: 3; }
  .page { padding: 20px 16px 40px; }
  .grid2 { grid-template-columns: 1fr; }
  .mrow-link { flex-direction: column; gap: 10px; }
  .public-grid { grid-template-columns: minmax(0, 1fr); }
  .notif { width: min(360px, 92vw); }
}

