cd /tmp/claude-0/-root/a2db516c-9100-4760-bff1-2f9fe28ddb93/scratchpad/pw && cat > walk.mjs <<'EOF'
import { chromium } from 'playwright-core'
const BASE = 'http://5.9.117.80:3000/'
const OUT = process.env.OUT
const errors = []
const browser = await chromium.launch({ executablePath: '/usr/bin/google-chrome', args: ['--no-sandbox'] })
async function session(viewport) {
  const ctx = await browser.newContext({ viewport })
  const page = await ctx.newPage()
  page.on('pageerror', (e) => errors.push(`pageerror ${page.url()}: ${e.message}`))
  page.on('console', (m) => m.type() === 'error' && errors.push(`console ${page.url()}: ${m.text()}`))
  page.on('response', (r) => r.status() >= 400 && r.url().includes('/api/') && !r.url().includes('/auth/me') && errors.push(`${r.status()} ${r.request().method()} ${r.url()}`))
  await page.goto(BASE)
  await page.fill('input[type=email]', process.env.EMAIL)
  await page.fill('input[type=password]', process.env.PW)
  await page.click('button.primary')
  await page.waitForSelector('.rail')
  return page
}
const shot = async (page, name, full = true) => { await page.waitForTimeout(900); await page.screenshot({ path: `${OUT}/${name}.png`, fullPage: full }) }
const page = await session({ width: 1440, height: 900 })
const routes = [['mycalls', '#/'], ['team', '#/team'], ['shared', '#/shared'], ['search', '#/search?q=battery'], ['folders', '#/folders'],
  ['playlists', '#/playlists'], ['companies', '#/companies'], ['trackers', '#/trackers'], ['coaching', '#/coaching'], ['ask', '#/ask'],
  ['settings', '#/settings'], ['admin-members', '#/admin/members'], ['admin-teams', '#/admin/teams'], ['admin-types', '#/admin/meeting-types'],
  ['admin-templates', '#/admin/templates'], ['admin-scorecards', '#/admin/scorecards'], ['admin-dictionary', '#/admin/dictionary']]
for (const [n, r] of routes) { await page.goto(BASE + r); await shot(page, n) }
// drill into first items
const ids = await page.evaluate(async () => {
  const j = (p) => fetch('/api' + p).then((r) => r.json())
  const [ms, fs, ps, cs, ts] = await Promise.all([j('/meetings'), j('/folders'), j('/playlists'), j('/companies'), j('/trackers')])
  return { meeting: ms.find((m) => m.title.startsWith('Kickoff'))?.id || ms[0]?.id, video: ms.find((m) => m.has_video)?.id, folder: fs[0]?.id, playlist: ps[0]?.id, company: cs[0]?.domain, tracker: ts[0]?.id }
})
for (const [n, r] of [['folder', `#/folders/${ids.folder}`], ['playlist', `#/playlists/${ids.playlist}`], ['company', `#/companies/${ids.company}`], ['tracker', `#/trackers/${ids.tracker}`]]) {
  await page.goto(BASE + r); await shot(page, n)
}
await page.goto(BASE + `#/meeting/${ids.meeting}`)
await shot(page, 'meeting-summary', false)
for (const tab of ['actions', 'ask', 'clips', 'comments', 'insights']) { await page.goto(BASE + `#/meeting/${ids.meeting}?tab=${tab}`); await shot(page, `meeting-${tab}`, false) }
await page.goto(BASE + `#/meeting/${ids.video}`); await shot(page, 'meeting-video', false)
// interactions: play, highlight, ask
await page.goto(BASE + `#/meeting/${ids.meeting}?tab=ask`)
await page.waitForTimeout(800)
const askInput = page.locator('.mt-ask input, .mt-ask textarea').first()
if (await askInput.count()) { await askInput.fill('What price was agreed?'); await askInput.press('Enter'); await page.waitForTimeout(12000); await shot(page, 'meeting-ask-answer', false) }
else errors.push('no ask input found')
const m = await session({ width: 390, height: 844 })
for (const [n, r] of [['m-mycalls', '#/'], ['m-meeting', `#/meeting/${ids.meeting}`], ['m-admin', '#/admin/members'], ['m-coaching', '#/coaching']]) {
  await m.goto(BASE + r); await m.waitForTimeout(900)
  const overflow = await m.evaluate(() => document.documentElement.scrollWidth - window.innerWidth)
  if (overflow > 1) errors.push(`horizontal overflow ${overflow}px on mobile ${r}`)
  await shot(m, n)
}
console.log(JSON.stringify({ ids, errors }, null, 1))
await browser.close()
EOF
