before("chapter = 'Team intelligence'", "await block(12)\n")
before("await cap(10, 'Coaching:", "await block(13)\n")
before("await cap(10, 'Playlists collect", "await block(14)\n")
before("chapter = 'Upload a recording'\nawait cap(11, 'New recordings", "await block(15)\n")
before("chapter = 'Admin, while it processes'", "await block(16)\n")
before("chapter = 'Upload a recording'\nawait cap(11, 'Done.", "await block(17)\n")
before("chapter = 'Wrap-up'", "await block(18)\n")

# ---- end: settle last block, stop capture, save timeline
a = s.index("await hold(10000)\n\nawait cdp.send('Page.stopScreencast')")
